	public function map(Closure $callable):array{
		$result = [];

		foreach(self::DATA as $id => $row){
			$data = array_merge(
				array_combine(Item::KEYS_DATA, $row),
				[Item::DESC_NAME => self::NAMES[$id][$this->lang->id]],
			);

			$result[$id] = $callable(new Item($data, $this->lang), $id);
		}

		return $result;
	}

	public function get(int $id):Item{

		if(!array_key_exists($id, self::DATA)){
			throw new InvalidArgumentException('invalid equipment item ID');
		}

		$itemData = array_merge(
			array_combine(Item::KEYS_DATA, self::DATA[$id]),
			[Item::DESC_NAME => self::NAMES[$id][$this->lang->id]],
		);

		$itemData[Item::DATA_ATTRIBUTE]  ??= A::NONE;

		return new Item($itemData, $this->lang);
	}

}
